package service

import "github.com/QuantumNous/new-api/model"

// The request ID is generated by the server, never supplied by the app.
type AppBetaFunding struct {
	userID    int
	requestID string
	reserved  int
}

func (f *AppBetaFunding) Source() string { return model.BetaSource }
func (f *AppBetaFunding) PreConsume(amount int) error {
	if err := model.ReserveAppBeta(f.userID, f.requestID, int64(f.reserved)+int64(amount)); err != nil {
		return err
	}
	f.reserved += amount
	return nil
}
func (f *AppBetaFunding) Settle(delta int) error {
	return model.FinishAppBeta(f.userID, f.requestID, int64(f.reserved)+int64(delta), false)
}
func (f *AppBetaFunding) Refund() error { return model.FinishAppBeta(f.userID, f.requestID, 0, true) }
